import { precacheAndRoute, createHandlerBoundToURL } from 'workbox-precaching';
import { NavigationRoute, registerRoute } from 'workbox-routing';
import { NetworkFirst, StaleWhileRevalidate, CacheFirst } from 'workbox-strategies';
import { CacheableResponsePlugin } from 'workbox-cacheable-response';
import { ExpirationPlugin } from 'workbox-expiration';

// Precache all assets generated by Vite
// The __WB_MANIFEST placeholder will be replaced by the actual list of assets during build
precacheAndRoute(self.__WB_MANIFEST);

// v2: forces a clean cache rebuild so entries poisoned by the old
// cache-first navigation (HTML stored under asset URLs) are dropped.
const HTML_CACHE_NAME = 'noor-connect-html-v2';
const ASSET_CACHE_NAME = 'noor-connect-assets-v2';
const API_CACHE_NAME = 'noor-connect-api-v2';
const HADITH_CACHE_NAME = 'noor-connect-hadith-v2';
const NASHEED_CACHE_NAME = 'noor-connect-nasheed-v2';

// Serve index.html for all navigation requests (SPA routing fallback).
// CRITICAL: network-first so every navigation gets the FRESH index.html
// after a redeploy. The old cache-first precache handler served stale
// HTML that referenced deleted chunks (MIME-type / "Failed to fetch
// dynamically imported module" errors). Cached HTML is only used when
// the network is unavailable (offline fallback).
try {
  const offlineHandler = createHandlerBoundToURL('/index.html');
  const navigationRoute = new NavigationRoute(
    async (args) => {
      try {
        return await new NetworkFirst({
          cacheName: HTML_CACHE_NAME,
          networkTimeoutSeconds: 3,
          plugins: [new CacheableResponsePlugin({ statuses: [200] })],
        }).handle(args);
      } catch (err) {
        console.log('SW: Navigation offline — serving precached index.html');
        return offlineHandler(args);
      }
    },
    { allowlist: [new RegExp('^/')] } // allow all navigation routes
  );
  registerRoute(navigationRoute);
} catch (e) {
  console.log('SW: Error setting up navigation route', e);
}

// Reject HTML responses from the asset cache: a missing chunk request
// rewritten to index.html returns 200 + text/html and must never be
// cached under a .js/.css URL (it would brick the app until the cache
// expired).
const noHtmlCachePlugin = {
  cacheWillUpdate: async ({ request, response }) => {
    if (!response || !response.ok) return null;
    const contentType = response.headers.get('content-type') || '';
    if (contentType.includes('text/html')) return null;
    return response;
  },
};

registerRoute(
  ({ request }) => ['script', 'style', 'worker'].includes(request.destination),
  new StaleWhileRevalidate({
    cacheName: ASSET_CACHE_NAME,
    plugins: [
      noHtmlCachePlugin,
      new CacheableResponsePlugin({ statuses: [200], types: ['basic'] }),
      new ExpirationPlugin({ maxEntries: 100, maxAgeSeconds: 7 * 24 * 60 * 60 }),
    ],
  })
);

registerRoute(
  ({ request, url }) => request.method === 'GET' && (url.pathname.startsWith('/api/') || url.hostname.includes('aladhan.com')),
  new NetworkFirst({
    cacheName: API_CACHE_NAME,
    networkTimeoutSeconds: 5,
    plugins: [
      new CacheableResponsePlugin({ statuses: [0, 200], types: ['basic', 'opaque'] }),
      new ExpirationPlugin({ maxEntries: 50, maxAgeSeconds: 24 * 60 * 60 }),
    ],
  })
);

// Nasheed audio from CDN — CacheFirst for offline + weak WiFi
registerRoute(
  ({ url }) => url.hostname === 'noor-nasheed-cdn.arifubaid0345.workers.dev',
  new CacheFirst({
    cacheName: NASHEED_CACHE_NAME,
    plugins: [
      new CacheableResponsePlugin({ statuses: [0, 200] }),
      new ExpirationPlugin({ maxEntries: 200, maxAgeSeconds: 90 * 24 * 60 * 60, purgeOnQuotaError: true }),
    ],
  })
);

// Islamic prayer times and events data - populated dynamically from the app
let PRAYER_TIMES = {};
let lastCheckDate = '';

// Approximate Islamic calendar offsets from Gregorian for event estimation.
// Ramadan regresses ~11 days/year. Base: Ramadan 1447 ≈ Feb 18, 2026.
const RAMADAN_BASE_YEAR = 2026;
const RAMADAN_BASE_DATE = new Date('2026-02-18');
const DAYS_PER_YEAR = 365.25;
const HIJRI_YEAR_DAYS = 354.367; // ~10.63 days shorter

function getEstimatedRamadan(year) {
  const diffYears = year - RAMADAN_BASE_YEAR;
  const offset = Math.round(diffYears * (DAYS_PER_YEAR - HIJRI_YEAR_DAYS));
  const start = new Date(RAMADAN_BASE_DATE);
  start.setDate(start.getDate() - offset);
  return start;
}

function getEidFitrDate(year) {
  const ramadan = getEstimatedRamadan(year);
  const eid = new Date(ramadan);
  eid.setDate(eid.getDate() + 29); // ~29 days after Ramadan start
  return eid;
}

function getEidAdhaDate(year) {
  const ramadan = getEstimatedRamadan(year);
  const eid = new Date(ramadan);
  eid.setDate(eid.getDate() + 70); // ~70 days after Ramadan start (10 Dhul Hijjah)
  return eid;
}

function getFridayKahfConfig() {
  return { day: 5, time: '10:00' };
}

// Notification history storage
let notificationHistory = [];

// Install event - skip waiting to ensure immediate update
self.addEventListener('install', (event) => {
  self.skipWaiting();
});

// Activate event - clean up caches and claim clients
self.addEventListener('activate', (event) => {
  const currentCaches = [HTML_CACHE_NAME, ASSET_CACHE_NAME, API_CACHE_NAME, HADITH_CACHE_NAME, NASHEED_CACHE_NAME];
  event.waitUntil(
    caches.keys().then((cacheNames) => {
      return Promise.all(
        cacheNames.map((cacheName) => {
          // Clean up old caches
          if ((cacheName.startsWith('noor-connect-') || cacheName === HADITH_CACHE_NAME) && !currentCaches.includes(cacheName)) {
            console.log('Service Worker: Clearing old cache:', cacheName);
            return caches.delete(cacheName);
          }
        })
      );
    }).then(() => {
      console.log('Service Worker: Activation complete, claiming clients');
      return self.clients.claim();
    })
  );
});

// Background sync and periodic sync
self.addEventListener('sync', (event) => {
  console.log('Service Worker: Background sync triggered:', event.tag);
  if (event.tag === 'prayer-times-check') {
    event.waitUntil(checkPrayerTimes());
  } else if (event.tag === 'islamic-events-check') {
    event.waitUntil(checkIslamicEvents());
  }
});

// Periodic sync for background checks
self.addEventListener('periodicsync', (event) => {
  console.log('Service Worker: Periodic sync triggered:', event.tag);
  if (event.tag === 'prayer-times-check') {
    event.waitUntil(checkPrayerTimes());
  } else if (event.tag === 'islamic-events-check') {
    event.waitUntil(checkIslamicEvents());
  }
});

// Push notification handler
self.addEventListener('push', (event) => {
  console.log('Service Worker: Push notification received');

  if (!event.data) {
    return;
  }

  const data = event.data.json();
  const options = {
    body: data.body,
    icon: '/icon-192x192.png',
    badge: '/icon-192x192.png',
    vibrate: [200, 100, 200],
    data: data.data || {},
    actions: data.actions || [],
    requireInteraction: data.requireInteraction || false,
    silent: data.silent || false,
    tag: data.tag || 'default'
  };

  event.waitUntil(
    self.registration.showNotification(data.title, options)
  );
});

// Notification click handler
self.addEventListener('notificationclick', (event) => {
  console.log('Service Worker: Notification clicked');

  event.notification.close();

  const urlToOpen = event.notification.data?.url || '/';

  event.waitUntil(
    clients.matchAll({ type: 'window', includeUncontrolled: true })
      .then((clientList) => {
        // Focus existing window if open
        for (const client of clientList) {
          if (client.url === urlToOpen && 'focus' in client) {
            return client.focus();
          }
        }

        // Open new window
        if (clients.openWindow) {
          return clients.openWindow(urlToOpen);
        }
      })
  );
});

const sentPrayerAlerts = {};

async function checkPrayerTimes() {
  try {
    const now = new Date();
    const currentMinutes = now.getHours() * 60 + now.getMinutes();
    const today = now.toDateString();

    // Reset sent alerts at midnight for a new day
    if (lastCheckDate !== today) {
      lastCheckDate = today;
      Object.keys(sentPrayerAlerts).forEach(k => delete sentPrayerAlerts[k]);
    }

    // Check prayer times with a 2-minute window to handle 15-min check interval
    for (const [prayer, data] of Object.entries(PRAYER_TIMES)) {
      if (!data.time || sentPrayerAlerts[prayer]) continue;

      const [h, m] = data.time.split(':').map(Number);
      if (isNaN(h) || isNaN(m)) continue;

      const prayerMinutes = h * 60 + m;
      const diff = Math.abs(currentMinutes - prayerMinutes);

      // Fire if within 2 minutes of the exact time (accounts for 15-min check interval)
      if (diff <= 2) {
        sentPrayerAlerts[prayer] = true;
        await sendPrayerNotification(prayer, data);
      }
    }
  } catch (error) {
    console.error('Service Worker: Error checking prayer times:', error);
  }
}

// Check Islamic events and send notifications
async function checkIslamicEvents() {
  try {
    console.log('Service Worker: Checking Islamic events...');

    const now = new Date();
    const year = now.getFullYear();
    const ramadanStart = getEstimatedRamadan(year);
    const ramadanCountdownStart = new Date(ramadanStart);
    ramadanCountdownStart.setDate(ramadanStart.getDate() - 30);

    // Check Ramadan countdown only if within the 30-day window before Ramadan
    if (now >= ramadanCountdownStart && now < ramadanStart) {
      const daysUntil = Math.ceil((ramadanStart - now) / (1000 * 60 * 60 * 24));
      await sendRamadanCountdownNotification(daysUntil);
    }

    // Check Eid events
    const eidFitr = getEidFitrDate(year);
    const eidAdha = getEidAdhaDate(year);

    if (now.toDateString() === eidFitr.toDateString()) {
      await sendEidNotification('Eid-ul-Fitr');
    }

    if (now.toDateString() === eidAdha.toDateString()) {
      await sendEidNotification('Eid-ul-Adha');
    }

    // Check Friday Surah Kahf reminder
    const fridayConfig = getFridayKahfConfig();
    if (now.getDay() === fridayConfig.day &&
      formatTime(now) === fridayConfig.time) {
      await sendFridayKahfNotification();
    }
  } catch (error) {
    console.error('Service Worker: Error checking Islamic events:', error);
  }
}

// Send prayer time notification
async function sendPrayerNotification(prayer, config) {
  const title = `${prayer.charAt(0).toUpperCase() + prayer.slice(1)} Adhan`;
  const body = `It's time for ${prayer} prayer. Click to play Adhan.`;

  await showNotification({
    title,
    body,
    tag: `prayer-${prayer}`,
    requireInteraction: true,
    data: {
      url: '/',
      prayer,
      adhan: config.adhan
    },
    actions: [
      {
        action: 'play-adhan',
        title: 'Play Adhan'
      }
    ]
  });

  addToHistory({ type: 'prayer', title, body, timestamp: Date.now() });
}

// Send Ramadan countdown notification
async function sendRamadanCountdownNotification(daysUntil) {
  const title = 'Ramadan Countdown';
  const body = `${daysUntil} day${daysUntil > 1 ? 's' : ''} until Ramadan 1447 AH`;

  await showNotification({
    title,
    body,
    tag: 'ramadan-countdown',
    data: {
      url: '/ramadan'
    }
  });

  addToHistory({ type: 'ramadan-countdown', title, body, timestamp: Date.now() });
}

// Send Eid notification
async function sendEidNotification(eidName) {
  const title = eidName;
  const body = `Eid Mubarak! May Allah accept your good deeds and fasting.`;

  await showNotification({
    title,
    body,
    tag: 'eid-greeting',
    requireInteraction: true,
    data: {
      url: '/',
      eid: eidName
    }
  });

  addToHistory({ type: 'eid', title, body, timestamp: Date.now() });
}

// Send Friday Kahf notification
async function sendFridayKahfNotification() {
  const title = 'Friday Reminder';
  const body = 'Don\'t forget to read Surah Al-Kahf today! It\'s a Sunnah with great rewards.';

  await showNotification({
    title,
    body,
    tag: 'friday-kahf',
    data: {
      url: '/quran/18'
    }
  });

  addToHistory({ type: 'friday-kahf', title, body, timestamp: Date.now() });
}

// Helper function to show notifications
async function showNotification(options) {
  try {
    // Check if we have permission before showing notification
    // In service worker, we can only check existing permission, not request it
    // Note: Cannot reliably check notification permission in service worker
    // getNotifications() returns [] (empty array) when no notifications, not null
    // Permission should be checked in main thread and communicated via postMessage
    // For now, we proceed with showing notification (will fail silently if no permission)

    await self.registration.showNotification(options.title, {
      body: options.body,
      icon: '/icon-192x192.png',
      badge: '/icon-192x192.png',
      vibrate: [500, 200, 500, 200, 500, 200, 500], // Longer vibration for alarm
      data: options.data || {},
      actions: options.actions || [],
      requireInteraction: true,
      renotify: true, // Wake up screen if same tag
      silent: false, // Ensure it makes sound
      tag: options.tag || 'default'
    });
  } catch (error) {
    console.error('Service Worker: Failed to show notification:', error);
  }
}

// Add notification to history
function addToHistory(notification) {
  notificationHistory.unshift(notification);

  // Keep only last 100 notifications
  if (notificationHistory.length > 100) {
    notificationHistory = notificationHistory.slice(0, 100);
  }

  // Save to IndexedDB or localStorage via client message
  self.clients.matchAll().then(clients => {
    clients.forEach(client => {
      client.postMessage({
        type: 'NOTIFICATION_HISTORY_UPDATE',
        data: notificationHistory
      });
    });
  });
}

// Format time helper
function formatTime(date) {
  const hours = date.getHours().toString().padStart(2, '0');
  const minutes = date.getMinutes().toString().padStart(2, '0');
  return `${hours}:${minutes}`;
}

// Message handler from client
self.addEventListener('message', (event) => {
  const data = event.data;

  switch (data.type) {
    case 'GET_NOTIFICATION_HISTORY':
      event.ports[0].postMessage({
        type: 'NOTIFICATION_HISTORY',
        data: notificationHistory
      });
      break;

    case 'CLEAR_NOTIFICATION_HISTORY':
      notificationHistory = [];
      event.ports[0].postMessage({
        type: 'NOTIFICATION_HISTORY_CLEARED'
      });
      break;

    case 'TRIGGER_PRAYER_CHECK':
      checkPrayerTimes();
      break;

    case 'TRIGGER_ISLAMIC_EVENTS_CHECK':
      checkIslamicEvents();
      break;

    case 'UPDATE_PRAYER_TIMES':
      // Clients post { type, data: { timings } }; accept the legacy flat
      // shape too so a mismatch can never silently blank the timings table.
      PRAYER_TIMES = (data.data && data.data.timings) || data.timings || {};
      console.log('Service Worker: Prayer times updated:', Object.keys(PRAYER_TIMES).length, 'prayers');
      break;

    case 'TEST_NOTIFICATION':
      // Handle test notification request
      showNotification({
        title: '🕌 Test Notification',
        body: 'Service Worker test notification successful!',
        tag: 'test-sw',
        requireInteraction: false,
        data: { test: true }
      });
      break;
  }
});

// Start periodic checks
function startPeriodicChecks() {
  // Check prayer times every 15 minutes instead of every minute
  // Prayer times only change daily, so frequent checks are wasteful
  setInterval(checkPrayerTimes, 900000); // Changed from 60000ms (1 min) to 900000ms (15 min)

  // Check Islamic events every hour
  setInterval(checkIslamicEvents, 3600000);

  // Initial checks
  checkPrayerTimes();
  checkIslamicEvents();
}

// Initialize background checks
startPeriodicChecks();

console.log('Service Worker: Loaded and ready');
